exercise.solution:
const ACTION_VERBS = [
  "built",
  "designed",
  "implemented",
  "reduced",
  "improved",
  "automated",
  "migrated",
  "led",
  "created",
  "delivered"
];

function reviewBullet(text) {
  const trimmed = typeof text === "string" ? text.trim() : "";
  const firstWord = trimmed.split(/\s+/)[0]?.replace(/^[^a-z]+|[^a-z]+$/gi, "").toLowerCase() ?? "";
  const hasActionVerb = ACTION_VERBS.includes(firstWord);
  const hasDigit = /\d/.test(trimmed);
  const validLength = trimmed.length >= 40 && trimmed.length <= 160;
  const hasPassivePhrase = /responsible for|worked on/i.test(trimmed);

  let score = 0;
  const tips = [];

  if (hasActionVerb) score += 1;
  else tips.push("Start with an action verb");

  if (hasDigit) score += 1;
  else tips.push("Add a number that shows impact");

  if (validLength) score += 1;
  else tips.push("Keep it between 40 and 160 characters");

  if (!hasPassivePhrase) score += 1;
  else tips.push("Avoid passive phrases like 'responsible for'");

  return { score, tips };
}

function starCheck(answer) {
  const parts = ["situation", "task", "action", "result"];
  const missing = [];

  for (const part of parts) {
    const value = answer?.[part];
    if (typeof value !== "string" || value.trim() === "") {
      missing.push(part);
    }
  }

  const result = answer?.result;
  if (typeof result === "string" && result.trim() !== "" && !/\d/.test(result)) {
    missing.push("result needs a number");
  }

  return missing;
}

