const expected = ["built", "designed", "implemented", "reduced", "improved", "automated", "migrated", "led", "created", "delivered"];
if (!Array.isArray(ACTION_VERBS)) throw new Error("ACTION_VERBS must be an array");
if (JSON.stringify(ACTION_VERBS) !== JSON.stringify(expected)) throw new Error("ACTION_VERBS does not match the required list");
return true;

const result = reviewBullet("Built 12 REST endpoints for customer support, improving access to ticket workflows across the portal.");
if (result.score !== 4) throw new Error("Expected full score");
if (result.tips.length !== 0) throw new Error("Expected no tips");
return true;

const result = reviewBullet("Designed, 8 reusable React components for the customer portal interface and reduced duplicate UI code significantly.");
if (result.score !== 4) throw new Error("Action verb punctuation or case was handled incorrectly");
return true;

const result = reviewBullet("Worked on backend development");
const expected = ["Start with an action verb", "Add a number that shows impact", "Keep it between 40 and 160 characters", "Avoid passive phrases like 'responsible for'"];
if (JSON.stringify(result.tips) !== JSON.stringify(expected)) throw new Error("Tips are missing or in the wrong order");
if (result.score !== 0) throw new Error("Expected zero score");
return true;

const result = reviewBullet("Built a useful feature for the team");
if (result.score !== 2) throw new Error("Expected points for the action verb and for avoiding passive phrases");
if (JSON.stringify(result.tips) !== JSON.stringify(["Add a number that shows impact", "Keep it between 40 and 160 characters"])) throw new Error("Unexpected tips");
return true;

const exactly40 = "Built " + "a".repeat(30) + " 123";
const result40 = reviewBullet(exactly40);
if (exactly40.trim().length !== 40) throw new Error("Test setup failed");
if (result40.tips.includes("Keep it between 40 and 160 characters")) throw new Error("40 characters should be valid");
const exactly160 = "Built " + "a".repeat(150) + " 123";
const result160 = reviewBullet(exactly160);
if (exactly160.trim().length !== 160) throw new Error("Test setup failed");
if (result160.tips.includes("Keep it between 40 and 160 characters")) throw new Error("160 characters should be valid");
return true;

const result = reviewBullet("Built 10 features while being RESPONSIBLE FOR maintaining the customer portal and supporting releases.");
if (result.score !== 3) throw new Error("Expected passive phrase to lose one point");
if (JSON.stringify(result.tips) !== JSON.stringify(["Avoid passive phrases like 'responsible for'"])) throw new Error("Wrong passive-phrase tip");
return true;

const result = starCheck({ situation: "", action: "Implemented the fix" });
const expected = ["situation", "task", "result"];
if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error("Missing STAR parts are incorrect");
return true;

const result = starCheck({
  situation: "CI builds were slow",
  task: "Improve the pipeline",
  action: "Added dependency caching and parallel test execution",
  result: "Reduced build time by 40 percent"
});
if (result.length !== 0) throw new Error("Complete STAR answer should have no warnings");
return true;

const result = starCheck({
  situation: "Customers had slow searches",
  task: "Improve search performance",
  action: "Added a database index",
  result: "Searches became much faster"
});
if (JSON.stringify(result) !== JSON.stringify(["result needs a number"])) throw new Error("Expected numeric result warning");
return true;

const result = starCheck({ situation: "  ", task: null, action: "Implemented a fix", result: "" });
const expected = ["situation", "task", "result"];
if (JSON.stringify(result) !== JSON.stringify(expected)) throw new Error("Blank and missing STAR parts were handled incorrectly");
return true;
